define(['jquery'], function($) {
    "use strict";

    return {
        init: function() {
            // 1. Initialize Scroll To Top
            const backToTopBtn = document.getElementById('backToTop');
            if (backToTopBtn) {
                window.addEventListener('scroll', function() {
                    if (window.scrollY > 300) {
                        backToTopBtn.classList.add('visible');
                        backToTopBtn.style.opacity = '1';
                        backToTopBtn.style.pointerEvents = 'auto';
                    } else {
                        backToTopBtn.classList.remove('visible');
                        backToTopBtn.style.opacity = '0';
                        backToTopBtn.style.pointerEvents = 'none';
                    }
                });

                backToTopBtn.addEventListener('click', function(e) {
                    e.preventDefault();
                    window.scrollTo({ top: 0, behavior: 'smooth' });
                });
            }

            // 2. Add 'scrolled' class to header on scroll
            const header = document.getElementById('header');
            if (header) {
                var scrollHandler = function() {
                    if (window.scrollY > 10) {
                        header.classList.add('is-scrolled');
                    } else {
                        header.classList.remove('is-scrolled');
                    }
                };

                window.addEventListener('scroll', scrollHandler);
            }

            // 3. Safe initialization for edit switch (if exists)
            // This handles potential issues with edit switch that might not be present on all pages
            setTimeout(function() {
                const editSwitch = document.getElementById('switch-mode-control-input');
                if (editSwitch) {
                    // Only add event listener if the element exists
                    if (editSwitch.addEventListener) {
                        editSwitch.addEventListener('change', function() {
                            // Handle edit switch change if needed
                            // Usually Moodle core handles this, but we ensure it's safe
                        });
                    }
                }
            }, 500); // Small delay to ensure element is available

            // 4. Universal notification component initializer
            // This addresses the issue where notification dropdown doesn't work consistently across all page types
            // Wait for all other scripts to load and then ensure notification components are properly initialized
            $(window).on('load', function() {
                // Re-bind event handlers for notification dropdowns if they're not working
                setTimeout(function() {
                    // Find notification/popover regions and ensure they have proper event handlers
                    $('.popover-region-toggle, .notification-popover, .message_app').each(function() {
                        const $element = $(this);

                        // Check if the element already has event handlers
                        if ($element.length > 0) {
                            const events = $._data(this, 'events');
                            if (!events || !events.click) {
                                // Re-initialize the component if needed
                                // This is a fallback to ensure the component works across all page types
                                $element.attr('data-bs-toggle', 'dropdown');
                            }
                        }
                    });

                    // Re-trigger initialization for any popover/dropdown components
                    if (typeof initializeNotificationComponents === 'function') {
                        initializeNotificationComponents();
                    }
                }, 1000); // Delay to ensure all other scripts have run
            });

            // 5. Monitor DOM changes and re-initialize components if needed
            // This catches cases where components are dynamically added after initial load
            if (window.MutationObserver) {
                const observer = new MutationObserver(function(mutations) {
                    mutations.forEach(function(mutation) {
                        if (mutation.type === 'childList') {
                            // Check if any notification-related elements were added
                            mutation.addedNodes.forEach(function(node) {
                                if (node.nodeType === 1) { // Element node
                                    const $node = $(node);

                                    // Check if the added node or its children include notification components
                                    if ($node.hasClass('popover-region') ||
                                        $node.hasClass('notification-popover') ||
                                        $node.hasClass('message_app') ||
                                        $node.find('.popover-region, .notification-popover, .message_app').length > 0) {

                                        // Re-initialize notification components after a short delay
                                        if (typeof initializeNotificationComponents === 'function') {
                                            setTimeout(initializeNotificationComponents, 100);
                                        }
                                    }

                                    // Also check for edit switch if it gets added dynamically
                                    if (node.id === 'switch-mode-control-input' || node.querySelector('#switch-mode-control-input')) {
                                        const editSwitch = document.getElementById('switch-mode-control-input') || node.querySelector('#switch-mode-control-input');
                                        if (editSwitch && editSwitch.addEventListener) {
                                            editSwitch.addEventListener('change', function() {
                                                // Handle edit switch change if needed
                                            });
                                        }
                                    }
                                }
                            });
                        }
                    });
                });

                // Start observing the document body for changes
                if (document.body) {
                    observer.observe(document.body, {
                        childList: true,
                        subtree: true
                    });
                }
            }

            // 6. Initialize Tooltips (using Bootstrap 5 via Moodle core)
            // Moodle 4 usually handles this automatically, but we can force re-init if needed.

            // Helper function to initialize notification components
            function initializeNotificationComponents() {
                // Ensure Bootstrap dropdowns are properly initialized
                if (typeof bootstrap !== 'undefined' && bootstrap.Dropdown) {
                    // Re-initialize any dropdown components that might have been affected
                    $('.dropdown-toggle').each(function() {
                        if ($(this).length > 0 && !$(this).data('bs.dropdown')) {
                            new bootstrap.Dropdown(this, {
                                boundary: 'clippingParents',
                                popperConfig: null
                            });
                        }
                    });
                }

                // Also ensure popover regions are properly initialized
                $('.popover-region-toggle').each(function() {
                    const $trigger = $(this);
                    if ($trigger.length > 0) {
                        const targetId = $trigger.attr('data-region');
                        if (targetId) {
                            // Ensure the toggle functionality is bound
                            $trigger.off('click.popover-region').on('click.popover-region', function(e) {
                                e.preventDefault();
                                // Trigger the default Moodle behavior
                                const region = document.querySelector('[data-region="' + targetId + '"]');
                                if (region) {
                                    region.classList.toggle('show');
                                }
                            });
                        }
                    }
                });
            }
        }
    };
});